/*
 * A098758  Smallest available integer which fits into the repeating pattern
 *          13579.
 * https://oeis.org/A098758
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  base, easy, nonn
 * Formula:   iterative construction - each term is the smallest unused number
 *            that is a contiguous block of the repeating digit pattern 13579.
 *            The sequence is generated by scanning the infinite string 13579
 *            13579 13579 … and at each step taking the next block of digits
 *            that yields a number not seen before
 * Range:     u8 n <= 11, u16 n <= 21, u32 n <= 38, u64 n <= 38, u128 n <= 38,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>

static seq_t nextdigit_map[10] = {
    0,                      /*0*/
    (seq_t)3,               /*1 ->3*/
    0,                      /*2*/
    (seq_t)5,               /*3 ->5*/
    0,                      /*4*/
    (seq_t)7,               /*5 ->7*/
    0,                      /*6*/
    (seq_t)9,               /*7 ->9*/
    0,                      /*8*/
    (seq_t)1                /*9 ->1*/
};

static seq_t pattern_digits[5] = { (seq_t)1, (seq_t)3, (seq_t)5, (seq_t)7, (seq_t)9 };

/* Dynamic array to cache computed sequence terms */
static seq_t *cache = NULL;
static idx_t cache_size = 0;
static idx_t cache_cap = 0;
static idx_t next_start_pos = 0;

/* Ensure the cache array can hold at least 'need' elements */
static void ensure_cache_capacity(idx_t need)
{
    if (need > cache_cap) {
        idx_t new_cap = cache_cap ? cache_cap * 2 : 64;
        while (new_cap < need)
            new_cap *= 2;
        cache = (seq_t *)realloc(cache, (size_t)new_cap * sizeof(seq_t));
        cache_cap = new_cap;
    }
}

/* Check if value 'x' is already in the cache (up to 'upto' elements). */
static bool in_cache(seq_t x, idx_t upto)
{
    for (idx_t i = 0; i < upto; ++i)
        if (cache[i] == x)
            return true;
    return false;
}

seq_t a(idx_t n)
{
    /* Generate terms up to index n */
    while (cache_size < n) {
        /* Start digit of the next block */
        seq_t cur = pattern_digits[next_start_pos % 5];
        idx_t cur_len = 1;                 /* number of digits so far */

        /* Extend until we find a value not yet in the cache */
        while (in_cache(cur, cache_size)) {
            unsigned int ld = (unsigned int)(cur % (seq_t)10); /* last digit */
            seq_t nd = nextdigit_map[ld];
            cur = cur * (seq_t)10 + nd;
            cur_len++;
        }

        /* Store the new term */
        ensure_cache_capacity(cache_size + 1);
        cache[cache_size++] = cur;

        /* Advance the start position by the length of this block */
        next_start_pos += cur_len;
    }

    return cache[n - 1];
}
